TASK
Combine repeated asynchronous calls by time or by pending execution.

PUBLIC CONTRACT
Module: await load('./index.js'); default export pDebounce, with pDebounce.promise.
pDebounce(fn, wait, options?) returns a function whose calls return promises. Calls within the wait window are combined, and the function runs with the latest arguments and receiver. wait is a finite number of milliseconds. before=true runs on the leading edge; otherwise it runs after the wait. The optional AbortSignal cancels pending debounced work.
pDebounce.promise(fn, options?) calls a Promise-returning/async function unless a previous execution is still pending; concurrent calls share that execution's fulfillment or rejection. With after=true, calls made during execution queue the latest arguments and receiver for a subsequent execution, and queued callers receive its result. Function failures propagate as promise rejections. A settled execution permits later calls to execute again.

SOURCE index.js
   1: const pDebounce = (functionToDebounce, wait, options = {}) => {
   2: 	if (!Number.isFinite(wait)) {
   3: 		throw new TypeError('Expected `wait` to be a finite number');
   4: 	}
   5: 
   6: 	let leadingValue;
   7: 	let timeout;
   8: 	let promiseHandlers = []; // Single array of {resolve, reject}
   9: 
  10: 	const onAbort = () => {
  11: 		clearTimeout(timeout);
  12: 		timeout = undefined;
  13: 
  14: 		try {
  15: 			options.signal?.throwIfAborted();
  16: 		} catch (error) {
  17: 			for (const {reject} of promiseHandlers) {
  18: 				reject(error);
  19: 			}
  20: 
  21: 			promiseHandlers = [];
  22: 		}
  23: 	};
  24: 
  25: 	return function (...arguments_) {
  26: 		return new Promise((resolve, reject) => {
  27: 			// Check if already aborted
  28: 			try {
  29: 				options.signal?.throwIfAborted();
  30: 			} catch (error) {
  31: 				reject(error);
  32: 				return;
  33: 			}
  34: 
  35: 			const shouldCallNow = options.before && !timeout;
  36: 
  37: 			clearTimeout(timeout);
  38: 
  39: 			timeout = setTimeout(async () => {
  40: 				timeout = undefined;
  41: 
  42: 				// Capture the current handlers for this execution
  43: 				const currentHandlers = promiseHandlers;
  44: 
  45: 				// Clear handlers for next cycle (new calls during execution will add to new list)
  46: 				promiseHandlers = [];
  47: 
  48: 				try {
  49: 					const result = options.before ? leadingValue : await functionToDebounce.apply(this, arguments_);
  50: 
  51: 					for (const {resolve: resolveFunction} of currentHandlers) {
  52: 						resolveFunction(result);
  53: 					}
  54: 				} catch (error) {
  55: 					for (const {reject: rejectFunction} of currentHandlers) {
  56: 						rejectFunction(error);
  57: 					}
  58: 				}
  59: 
  60: 				// Clear leading value for next cycle
  61: 				leadingValue = undefined;
  62: 
  63: 				// Remove abort listener
  64: 				options.signal?.removeEventListener('abort', onAbort);
  65: 			}, wait);
  66: 
  67: 			if (shouldCallNow) {
  68: 				// Execute immediately for leading edge
  69: 				(async () => {
  70: 					try {
  71: 						leadingValue = await functionToDebounce.apply(this, arguments_);
  72: 						resolve(leadingValue);
  73: 					} catch (error) {
  74: 						reject(error);
  75: 					}
  76: 				})();
  77: 			} else {
  78: 				// Add to handlers for later resolution
  79: 				promiseHandlers.push({resolve, reject});
  80: 
  81: 				// Set up abort listener (only once per batch)
  82: 				if (options.signal && promiseHandlers.length === 1) {
  83: 					options.signal.addEventListener('abort', onAbort, {once: true});
  84: 				}
  85: 			}
  86: 		});
  87: 	};
  88: };
  89: 
  90: pDebounce.promise = (function_, options = {}) => {
  91: 	let currentPromise;
  92: 	let queuedCall;
  93: 
  94: 	return async function (...arguments_) {
  95: 		if (currentPromise) {
  96: 			if (!options.after) {
  97: 				return currentPromise;
  98: 			}
  99: 
 100: 			// Queue latest call (replacing any existing queue)
 101: 			queuedCall ??= {resolvers: []};
 102: 			queuedCall.arguments = arguments_;
 103: 			queuedCall.context = this;
 104: 
 105: 			return new Promise((resolve, reject) => {
 106: 				queuedCall.resolvers.push({resolve, reject});
 107: 			});
 108: 		}
 109: 
 110: 		currentPromise = (async () => {
 111: 			let result;
 112: 			let initialError;
 113: 			let didReject = false;
 114: 
 115: 			try {
 116: 				result = await function_.apply(this, arguments_);
 117: 			} catch (error) {
 118: 				initialError = error;
 119: 				didReject = true;
 120: 			}
 121: 
 122: 			// Process queued calls regardless of initial result
 123: 			while (queuedCall) {
 124: 				const call = queuedCall;
 125: 				queuedCall = undefined;
 126: 
 127: 				try {
 128: 					// eslint-disable-next-line no-await-in-loop
 129: 					const queuedResult = await function_.apply(call.context, call.arguments);
 130: 					for (const {resolve} of call.resolvers) {
 131: 						resolve(queuedResult);
 132: 					}
 133: 				} catch (error) {
 134: 					for (const {reject} of call.resolvers) {
 135: 						reject(error);
 136: 					}
 137: 				}
 138: 			}
 139: 
 140: 			if (didReject) {
 141: 				throw initialError;
 142: 			}
 143: 
 144: 			return result;
 145: 		})();
 146: 
 147: 		try {
 148: 			return await currentPromise;
 149: 		} finally {
 150: 			currentPromise = undefined;
 151: 		}
 152: 	};
 153: };
 154: 
 155: export default pDebounce;

